import React, { useEffect, useState } from 'react';
import { FaPlane } from 'react-icons/fa';
import { useTheme } from '../context/ThemeContext';

const DecorativePlanes = () => {
  const { theme } = useTheme();
  const [planes, setPlanes] = useState([]);

  const calculateRotation = (startX, startY, endX, endY) => {
    const angle = Math.atan2(endY - startY, endX - startX) * (180 / Math.PI);
    return angle;
  };

  useEffect(() => {
    // Create initial planes
    const initialPlanes = Array.from({ length: 5 }, (_, index) => {
      const startX = Math.random() * 100;
      const startY = Math.random() * 100;
      const endX = Math.random() * 100;
      const endY = Math.random() * 100;
      return {
        id: index,
        startX,
        startY,
        endX,
        endY,
        duration: 8 + Math.random() * 7, // Random duration between 8-15s
        delay: Math.random() * 5, // Random delay between 0-5s
        size: 12 + Math.random() * 8, // Random size between 12-20px
        rotation: calculateRotation(startX, startY, endX, endY)
      };
    });
    setPlanes(initialPlanes);

    // Update plane positions periodically
    const interval = setInterval(() => {
      setPlanes(currentPlanes => 
        currentPlanes.map(plane => {
          const newEndX = Math.random() * 100;
          const newEndY = Math.random() * 100;
          return {
            ...plane,
            startX: plane.endX,
            startY: plane.endY,
            endX: newEndX,
            endY: newEndY,
            duration: 8 + Math.random() * 7,
            delay: 0,
            rotation: calculateRotation(plane.endX, plane.endY, newEndX, newEndY)
          };
        })
      );
    }, 15000); // Update every 15 seconds

    return () => clearInterval(interval);
  }, []);

  return (
    <div className="fixed inset-0 pointer-events-none overflow-hidden" style={{ zIndex: 0 }}>
      {planes.map(plane => (
        <div
          key={plane.id}
          className="absolute"
          style={{
            left: `${plane.startX}%`,
            top: `${plane.startY}%`,
            transform: `rotate(${plane.rotation}deg)`,
            animation: `fly-${plane.id} ${plane.duration}s linear ${plane.delay}s infinite`,
            opacity: 0.3,
            color: theme.primary
          }}
        >
          <FaPlane size={plane.size} />
        </div>
      ))}

      <style jsx>{`
        ${planes.map(plane => `
          @keyframes fly-${plane.id} {
            0% {
              transform: translate(0, 0) rotate(${plane.rotation}deg);
              opacity: 0;
            }
            10% {
              opacity: 0.3;
            }
            90% {
              opacity: 0.3;
            }
            100% {
              transform: translate(
                calc(${plane.endX}vw - ${plane.startX}vw),
                calc(${plane.endY}vh - ${plane.startY}vh)
              ) rotate(${plane.rotation}deg);
              opacity: 0;
            }
          }
        `).join('\n')}
      `}</style>
    </div>
  );
};

export default DecorativePlanes;
